#!/usr/bin/env node
// tier: T2
/**
 * audit-awareness-inject.mjs — UserPromptSubmit hook
 *
 * SYSTEM-AUDIT-AWARENESS/U-AUDIT-INJECT (slot:papa 2026-05-26)
 *
 * Surfaces relevant audits to chats based on prompt-keyword → domain match.
 * Reads state/shared/AUDIT-REGISTRY.json (generated by scripts/build-audit-registry.mjs).
 *
 * Goal directive: "make all other chats auto-remember we have audits of specific
 * domains" + "audits utilized on a 2-day time frame" (48h staleness gate).
 *
 * Behavior:
 *   - registry missing → silent pass
 *   - no keyword match → silent pass
 *   - K top hits, each tagged with staleness (fresh ≤24h | warn 24-48h | stale >48h)
 *   - stale rows surface a `node scripts/<script>` re-run hint
 *
 * Knobs:
 *   PRISM_AUDIT_AWARENESS_DISABLE=1   off
 *   PRISM_AUDIT_AWARENESS_K=N         top-K (default 3, clamp [1,8])
 *   PRISM_AUDIT_AWARENESS_STALE_HRS=N override registry's threshold for emit (default = registry)
 *   PRISM_AUDIT_AWARENESS_VERBOSE=1   include lastRunIso + ageHrs per row
 *
 * Karpathy R10 mechanism: gives every chat the same audit-awareness substrate
 * regardless of which slot it's in.
 */

import { readFileSync, statSync } from "node:fs";

const REGISTRY = "H:/prism/state/shared/AUDIT-REGISTRY.json";

function pass() { process.stdout.write(JSON.stringify({ continue: true })); }
function passWithCtx(ctx) {
  process.stdout.write(JSON.stringify({
    continue: true,
    hookSpecificOutput: { hookEventName: "UserPromptSubmit", additionalContext: ctx },
  }));
}

function clampInt(s, def, lo, hi) {
  const n = Number.parseInt(s ?? "", 10);
  if (!Number.isFinite(n)) return def;
  return Math.max(lo, Math.min(hi, n));
}

function readRegistrySafe() {
  try {
    const st = statSync(REGISTRY);
    if (!st || st.size === 0) return null;
    const body = readFileSync(REGISTRY, "utf8");
    return JSON.parse(body);
  } catch {
    return null;
  }
}

// Same DOMAIN_PATTERNS subset that's most useful for prompt-keyword matching.
// Order matters; first match wins per token.
const PROMPT_DOMAIN_RULES = [
  [/\bmill(ing)?\b/i, "mill"],
  [/\blathe\b|turning/i, "lathe"],
  [/\bwedm\b|wire[-_]edm\b|edm/i, "wedm"],
  [/\bcad\b/i, "cad"],
  [/\bcam\b|toolpath/i, "cam"],
  [/\bpost[-_]processor\b|post[-_]gen|\bpost\b/i, "post"],
  [/\bhook\b/i, "hook"],
  [/\bcron|scheduled[-_]task/i, "scheduled-task"],
  [/\bwiki\b/i, "wiki"],
  [/\bmemory\b|memories\b|MEMORY\.md/i, "memory"],
  [/\btribal\b/i, "tribal"],
  [/\bdocker\b/i, "docker"],
  [/\broadmap\b|milestone\b|envelope/i, "roadmap"],
  [/\bworktree\b/i, "worktree"],
  [/\borphan\b|unwired\b/i, "orphan"],
  [/\bcoverage\b/i, "coverage"],
  [/\bdrift\b/i, "drift"],
  [/\bjm[-_]?die\b/i, "jm-die"],
  [/\bclose[-_]out\b|shipped\s+but\s+pending/i, "close-out"],
  [/\bnudge\b|token[-_]savings/i, "token-savings"],
  [/\bprint[-_]to[-_]cnc|pipeline\b/i, "pipeline"],
  [/\bpsn\b/i, "psn"],
  [/\bagi\b|\bai\b/i, "ai"],
  [/\bsystem[-_]viz\b/i, "system-viz"],
];

function domainsFromPrompt(prompt) {
  if (!prompt || typeof prompt !== "string") return new Set();
  const out = new Set();
  for (const [re, d] of PROMPT_DOMAIN_RULES) {
    if (re.test(prompt)) out.add(d);
  }
  return out;
}

function formatRow(a, verbose) {
  const sidecarHint = a.sidecars?.[0]?.path
    ? ` · sidecar: \`${a.sidecars[0].path.replace("H:/prism/", "")}\``
    : "";
  const ageNote = a.ageHrs == null
    ? "no sidecar"
    : a.ageHrs < 1
      ? `${Math.round(a.ageHrs * 60)}m old`
      : a.ageHrs < 48
        ? `${a.ageHrs.toFixed(1)}h old`
        : `${(a.ageHrs / 24).toFixed(1)}d old`;
  const staleTag =
    a.staleness === "fresh" ? "✓ fresh" :
    a.staleness === "warn" ? "⚠ warn (>24h)" :
    "⛔ stale (>48h)";
  const rerunHint = a.scriptPath && a.staleness !== "fresh"
    ? ` · re-run: \`node ${a.scriptPath.replace("H:/prism/", "")}\``
    : "";
  const verbExtra = verbose && a.lastRunIso ? ` · lastRun: ${a.lastRunIso}` : "";
  return `- **${a.id}** (${a.domain}) — ${staleTag} · ${ageNote}${sidecarHint}${rerunHint}${verbExtra}`;
}

function main() {
  if (process.env.PRISM_AUDIT_AWARENESS_DISABLE === "1") return pass();
  const K = clampInt(process.env.PRISM_AUDIT_AWARENESS_K, 3, 1, 8);
  const verbose = process.env.PRISM_AUDIT_AWARENESS_VERBOSE === "1";

  // Read prompt from stdin
  let stdinText = "";
  try {
    stdinText = readFileSync(0, "utf8");
  } catch { /* no stdin */ }
  let payload;
  try { payload = JSON.parse(stdinText || "{}"); } catch { return pass(); }
  const prompt = payload?.prompt;
  if (!prompt) return pass();

  const reg = readRegistrySafe();
  if (!reg || !Array.isArray(reg.audits) || reg.audits.length === 0) return pass();

  const domains = domainsFromPrompt(prompt);
  if (domains.size === 0) return pass();

  // Filter audits by domain match, prefer stale rows (= surface what needs attention)
  const matches = reg.audits.filter((a) => domains.has(a.domain));
  if (matches.length === 0) return pass();

  // Sort: stale > warn > fresh; within group by ageHrs descending; non-orphan first
  matches.sort((a, b) => {
    const ord = { stale: 0, warn: 1, fresh: 2 };
    const ka = ord[a.staleness] ?? 0;
    const kb = ord[b.staleness] ?? 0;
    if (ka !== kb) return ka - kb;
    if (!!a.orphanSidecar !== !!b.orphanSidecar) return a.orphanSidecar ? 1 : -1;
    return (b.ageHrs ?? 0) - (a.ageHrs ?? 0);
  });

  const top = matches.slice(0, K);
  const lines = top.map((a) => formatRow(a, verbose));
  const summary = `${matches.length} audit(s) match this domain (${[...domains].join(", ")}); showing top ${top.length}`;
  const ctx = `## 🔍 PRISM Audit awareness — ${summary}\n${lines.join("\n")}\n\n_Source: \`state/shared/AUDIT-REGISTRY.json\` (regen \`node scripts/build-audit-registry.mjs\`). 2-day staleness threshold. Disable: \`PRISM_AUDIT_AWARENESS_DISABLE=1\`._`;
  passWithCtx(ctx);
}

try { main(); } catch { pass(); }
